namespace ghidra.app.plugin.core.debug.gui.breakpoint;








using docking;
using generic.theme.GThemeDefaults;
using generic.theme;
using ghidra.framework.plugintool;
using ghidra.pcode.exec.SleighUtils;
using ghidra.pcode.exec.SleighUtils;
using ghidra.util;

public abstract class AbstractDebuggerSleighInputDialog : DialogComponentProvider {
	protected static readonly Color COLOR_ERROR = Colors.ERROR;
	protected static readonly AttributeSet RED_UNDERLINE;

	static AbstractDebuggerSleighInputDialog() {
		MutableAttributeSet attributes = new SimpleAttributeSet();
		StyleConstants.setForeground(attributes, COLOR_ERROR);
		StyleConstants.setUnderline(attributes, true);
		RED_UNDERLINE = attributes;
	}

	protected JPanel panel;
	protected JLabel label;
	protected StyledDocument docInput;
	protected JTextPane textInput;
	private JScrollPane spInput;
	protected bool isValid = false;

	static class SleighTextPane : JTextPane {
		public SleighTextPane(StyledDocument document) : base(document)
    {
			Gui.registerFont(this, "font.debugger.sleigh");
		}
	}

	protected AbstractDebuggerSleighInputDialog(string title, string prompt) : base(title, true, true, true, false)
    {
		panel = new JPanel(new BorderLayout());
		panel.setBorder(new EmptyBorder(16, 16, 16, 16));
		label = new JLabel(prompt);
		label.getMaximumSize().width = 400;
		panel.add(label, BorderLayout.NORTH);

		docInput = new DefaultStyledDocument();
		textInput = new SleighTextPane(docInput);
		spInput = new JScrollPane(textInput);
		spInput.getMaximumSize().height = 300;
		panel.add(spInput);

		addWorkPanel(panel);

		addOKButton();
		addCancelButton();
	}

	public string prompt(PluginTool tool, string defaultInput) {
		setStatusText("");
		textInput.setText(defaultInput);
		validateAndMarkup();
		Swing.runLater(() => repack());
		textInput.selectAll();
		tool.showDialog(this);
		if (isValid) {
			return getInput();
		}
		return null;
	}

	/* @Override */
	protected void dialogShown() {
		base.dialogShown();
		textInput.requestFocus();
	}

	public string getInput() {
		return textInput.getText();
	}

	protected abstract void validate();

	protected void clearAttributes() {
		docInput.setCharacterAttributes(0, docInput.getLength() + 1, SimpleAttributeSet.EMPTY,
			true);
	}

	protected void addErrorAttribute(int start, int stop) {
		int length = stop - start + 1;
		docInput.setCharacterAttributes(start, length, RED_UNDERLINE, true);
	}

	protected void validateAndMarkup() {
		isValid = false;
		clearAttributes();
		try {
			validate();
			isValid = true;
		}
		catch (SleighParseError e) {
			setStatusText("<html><pre>" + HTMLUtilities.escapeHTML(e.getMessage()) + "</pre>",
				MessageType.ERROR, false);
			Swing.runLater(() => {
				if (spInput.getPreferredSize().height > spInput.getSize().height) {
					repack();
				}
			});
			foreach (SleighParseErrorEntry error in e.getErrors()) {
				addErrorAttribute(error.start(), error.stop());
			}
		}
	}

	/* @Override */
	protected void okCallback() {
		validateAndMarkup();
		if (isValid) {
			close();
		}
	}

	/* @Override */
	protected void cancelCallback() {
		isValid = false;
		close();
	}
}
